import React, { useState } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import { Star, ChevronRight, ChevronLeft, TrendingUp, Share2 } from 'lucide-react';
import PriceChart from '../components/PriceChart';
import Logo from '../components/Logo';
import { getStockDetail, relatedStocks } from '../data/mockData';
import { formatFcfa, formatPct, formatCompactFcfa } from '../lib/format';
import type { Stock, Dividend, CalendarEvent } from '../types';

const PERIODS = ['1J', '1S', '1M', '6M', '1A', '5A'];

export default function StockDetail() {
  const { ticker } = useParams<{ ticker: string }>();
  const navigate = useNavigate();

  const stock = getStockDetail(ticker ?? '');
  const related = relatedStocks(ticker ?? '', 4);
  const [period, setPeriod] = useState('1J');
  const [starred, setStarred] = useState(false);

  if (!stock) {
    return (
      <div className="mx-auto max-w-shell px-6 lg:px-10 py-24 text-center">
        <p className="text-muted mb-4">Valeur introuvable.</p>
        <Link to="/" className="text-ink font-semibold underline">
          Retour aux marchés
        </Link>
      </div>
    );
  }

  const positive = stock.changePct >= 0;
  const color = positive ? 'text-mint-deep' : stock.changePct < 0 ? 'text-loss' : 'text-muted';
  const absChange = (stock.price * stock.changePct) / 100;

  return (
    <div
      className="mx-auto max-w-shell px-6 lg:px-10 pt-8 pb-24 grid grid-cols-12 gap-8 lg:gap-12"
      data-testid={`page-stock-${stock.ticker}`}
    >
      <main className="col-span-12 lg:col-span-8">
        <button
          onClick={() => navigate(-1)}
          className="inline-flex items-center gap-1 text-[13px] text-muted hover:text-ink transition-colors mb-6"
          data-testid="btn-back"
        >
          <ChevronLeft size={16} /> Retour
        </button>

        <div className="flex items-start justify-between gap-6">
          <div className="min-w-0">
            <Logo ticker={stock.ticker} size={56} />
            <h1 className="mt-5 text-[36px] md:text-[40px] font-bold tracking-tight leading-tight">
              {stock.name}
            </h1>
            <div className="mt-1 text-[13px] text-muted num">
              {stock.ticker} · {stock.sector} · {stock.subIndustry}
            </div>
            <div className="mt-6 text-[44px] md:text-[52px] font-black num tracking-[-0.03em] leading-none">
              {formatFcfa(stock.price)}
            </div>
            <div className={`mt-3 text-[16px] font-bold num ${color}`} data-testid="stock-change">
              {positive ? '▲' : stock.changePct < 0 ? '▼' : '—'}{' '}
              {formatFcfa(Math.abs(absChange))} ({formatPct(stock.changePct)})
              <span className="text-muted font-normal ml-2">· Depuis 09:00</span>
            </div>
          </div>
          <div className="flex items-center gap-2 shrink-0">
            <button
              onClick={() => setStarred((s) => !s)}
              className="w-10 h-10 rounded-pill hover:bg-surface flex items-center justify-center transition-colors"
              data-testid="btn-star"
              aria-label="Favori"
            >
              <Star
                size={20}
                strokeWidth={1.8}
                className={starred ? 'text-mint-deep' : 'text-ink'}
                fill={starred ? '#00D084' : 'transparent'}
              />
            </button>
            <button
              className="w-10 h-10 rounded-pill hover:bg-surface flex items-center justify-center transition-colors"
              aria-label="Partager"
              data-testid="btn-share"
            >
              <Share2 size={18} strokeWidth={1.8} />
            </button>
          </div>
        </div>

        <div className="mt-8 flex items-center gap-1">
          {PERIODS.map((p) => (
            <button
              key={p}
              onClick={() => setPeriod(p)}
              className={`px-4 h-9 rounded-pill text-[13px] font-semibold transition-colors ${
                period === p ? 'bg-ink text-white' : 'text-muted hover:text-ink hover:bg-surface'
              }`}
              data-testid={`period-${p}`}
            >
              {p}
            </button>
          ))}
        </div>

        <div className="mt-5 -mx-1">
          <PriceChart
            ticker={stock.ticker}
            changePct={stock.changePct}
            lastPrice={stock.price}
            width={760}
            height={320}
          />
        </div>

        <div className="mt-1 grid grid-cols-6 text-[11px] text-muted num pr-16">
          {['09:00', '10:00', '11:00', '12:00', '13:00', '14:00'].map((t) => (
            <span key={t} className="text-center">
              {t}
            </span>
          ))}
        </div>

        <section className="mt-16" data-testid="section-metrics">
          <h2 className="text-[22px] font-bold tracking-tight">Métriques clés</h2>
          <div className="mt-6 grid grid-cols-2 md:grid-cols-4 gap-x-6 gap-y-8">
            <Stat label="Capitalisation" value={formatCompactFcfa(stock.mktCapBn * 1e9)} />
            <Stat label="PER" value={stock.peRatio} />
            <Stat label="Bêta 52s" value={stock.beta52w} />
            <Stat label="Rendement" value={`${stock.divYield} %`} />
            <Stat label="Ouverture" value={formatFcfa(stock.open)} />
            <Stat label="Clôture" value={formatFcfa(stock.close)} />
            <Stat label="Achat" value={formatFcfa(stock.bid)} />
            <Stat label="Vente" value={formatFcfa(stock.ask)} />
          </div>

          <div className="mt-10 grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-6">
            <MetricRange label="Séance" left={stock.dayLow} right={stock.dayHigh} current={stock.price} />
            <MetricRange
              label="52 semaines"
              left={stock.yearLow}
              right={stock.yearHigh}
              current={stock.price}
            />
          </div>
        </section>

        <section className="mt-16" data-testid="section-dividends">
          <button className="flex items-center gap-2 group">
            <h2 className="text-[22px] font-bold tracking-tight">Dividendes</h2>
            <ChevronRight
              size={20}
              className="text-muted group-hover:translate-x-0.5 transition-transform"
            />
          </button>
          <ul className="mt-6 space-y-4">
            {stock.dividends.map((d, i) => (
              <DividendRow
                key={i}
                dividend={d}
                maxValue={Math.max(...stock.dividends.map((x) => x.value))}
              />
            ))}
          </ul>
        </section>

        <section className="mt-16" data-testid="section-analysts">
          <h2 className="text-[22px] font-bold tracking-tight">Recommandations des analystes</h2>
          <div className="mt-6 flex items-baseline gap-3">
            <div className="text-[42px] font-bold num tracking-tight leading-none">
              {formatFcfa(stock.targetPrice)}
            </div>
            <div className="text-[13px] text-muted">objectif moyen</div>
          </div>
          <p className="mt-2 text-[13px] text-muted max-w-xl">
            Objectif de cours moyen. Estimation haute {formatFcfa(Math.round(stock.targetPrice * 1.18))},
            estimation basse {formatFcfa(Math.round(stock.targetPrice * 0.82))}. Cette valeur est suivie
            par {stock.analysts.count} analystes.
          </p>
          <div className="mt-6">
            <div className="flex h-2.5 rounded-full overflow-hidden bg-surface" data-testid="analysts-bar">
              <div style={{ width: `${stock.analysts.buy}%` }} className="bg-mint" />
              <div style={{ width: `${stock.analysts.hold}%` }} className="bg-black/70" />
              <div style={{ width: `${stock.analysts.sell}%` }} className="bg-loss" />
            </div>
            <div className="mt-5 grid grid-cols-3 gap-4">
              <RatingStat label="Acheter" pct={stock.analysts.buy} color="text-mint-deep" />
              <RatingStat label="Conserver" pct={stock.analysts.hold} color="text-ink" />
              <RatingStat label="Vendre" pct={stock.analysts.sell} color="text-loss" />
            </div>
          </div>
        </section>

        <section className="mt-16" data-testid="section-events">
          <h2 className="text-[22px] font-bold tracking-tight">Événements à venir</h2>
          <div className="mt-6 grid grid-cols-1 md:grid-cols-3 gap-4">
            {stock.events.map((e, i) => (
              <EventCard key={i} event={e} />
            ))}
          </div>
        </section>

        <section className="mt-16" data-testid="section-related">
          <h2 className="text-[22px] font-bold tracking-tight">Valeurs à découvrir</h2>
          <div className="mt-6 grid grid-cols-2 sm:grid-cols-4 gap-3">
            {related.map((r) => (
              <RelatedCard key={r.ticker} stock={r} />
            ))}
          </div>
        </section>

        <section className="mt-16">
          <h2 className="text-[22px] font-bold tracking-tight">À propos</h2>
          <p className="mt-4 text-[14px] text-ink/80 leading-relaxed max-w-3xl">{stock.about}</p>
          <p className="mt-3 text-[12px] text-muted">
            Les cotations, prévisions et notes d&apos;analystes affichées sont fictives et destinées à la
            démonstration de l&apos;interface.
          </p>
        </section>
      </main>

      <aside className="col-span-12 lg:col-span-4">
        <div className="lg:sticky lg:top-24 space-y-4">
          <div className="rounded-card bg-surface p-6 border hairline" data-testid="visitor-cta">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-10 h-10 rounded-full bg-mint-light flex items-center justify-center">
                <TrendingUp size={18} className="text-mint-deep" />
              </div>
              <div className="min-w-0">
                <h3 className="font-bold text-[16px] truncate">Investissez dans {stock.name}</h3>
                <p className="text-[13px] text-muted">Commission 0 % · Minimum 1 FCFA</p>
              </div>
            </div>
            <p className="text-[14px] text-muted mb-5 leading-relaxed">
              Créez votre compte Felix pour acheter et vendre des actions BRVM sans frais, directement
              depuis votre téléphone.
            </p>
            <button
              className="w-full h-12 rounded-pill bg-ink text-white font-semibold hover:opacity-90 transition-opacity"
              data-testid="btn-create-account"
            >
              Créer un compte
            </button>
            <button
              className="w-full h-12 rounded-pill mt-2 text-ink font-semibold hover:bg-white transition-colors"
              data-testid="btn-login-side"
            >
              Se connecter
            </button>
          </div>

          <div className="rounded-card border hairline p-6" data-testid="quick-facts">
            <h3 className="text-[13px] font-semibold text-muted uppercase tracking-widest mb-4">
              En bref
            </h3>
            <dl className="space-y-3 text-[14px]">
              <FactRow label="Ticker" value={stock.ticker} />
              <FactRow label="Secteur" value={stock.sector} />
              <FactRow label="Sous-secteur" value={stock.subIndustry} />
              <FactRow label="Marché" value="BRVM · UEMOA" />
              <FactRow label="Devise" value="FCFA (XOF)" />
            </dl>
          </div>
        </div>
      </aside>
    </div>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <div className="text-[12px] text-muted uppercase tracking-wider font-medium">{label}</div>
      <div className="mt-1.5 text-[18px] font-bold num tracking-tight">{value}</div>
    </div>
  );
}

function FactRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-center justify-between gap-3">
      <dt className="text-muted">{label}</dt>
      <dd className="font-semibold text-right truncate">{value}</dd>
    </div>
  );
}

function MetricRange({
  label,
  left,
  right,
  current,
}: {
  label: string;
  left: number;
  right: number;
  current: number;
}) {
  const pos = Math.max(0, Math.min(1, (current - left) / (right - left || 1)));
  return (
    <div>
      <div className="flex items-center justify-between text-[12px] text-muted mb-2 uppercase tracking-wider font-medium">
        <span>{label}</span>
      </div>
      <div className="grid grid-cols-[auto_1fr_auto] items-center gap-3">
        <span className="num font-semibold text-[13px] text-muted">
          {left.toLocaleString('fr-FR')}
        </span>
        <div className="relative h-1.5 rounded-full bg-surface">
          <div
            className="absolute top-1/2 -translate-y-1/2 h-3 w-1 rounded-full bg-ink"
            style={{ left: `calc(${pos * 100}% - 2px)` }}
          />
        </div>
        <span className="num font-semibold text-[13px] text-muted">
          {right.toLocaleString('fr-FR')}
        </span>
      </div>
    </div>
  );
}

function RatingStat({ label, pct, color }: { label: string; pct: number; color: string }) {
  return (
    <div>
      <div className={`text-[13px] font-semibold ${color}`}>{label}</div>
      <div className="text-[22px] font-bold num mt-1">{`${pct} %`}</div>
    </div>
  );
}

function DividendRow({ dividend, maxValue }: { dividend: Dividend; maxValue: number }) {
  const pct = (dividend.value / maxValue) * 100;
  return (
    <li className="grid grid-cols-[80px_1fr_auto] items-center gap-4">
      <span className="text-[13px] text-muted">{dividend.period}</span>
      <div className="h-2 rounded-full bg-surface overflow-hidden">
        <div className="h-full bg-mint" style={{ width: `${pct}%` }} />
      </div>
      <span className="text-[13px] font-semibold num">{`${dividend.value.toLocaleString('fr-FR')} FCFA`}</span>
    </li>
  );
}

function EventCard({ event }: { event: CalendarEvent }) {
  return (
    <div className="rounded-card border hairline p-5">
      <div className="flex items-baseline gap-2">
        <span className="text-[26px] font-bold leading-none">{event.day}</span>
        <span className="text-[12px] text-muted">{event.month}</span>
      </div>
      <div className="mt-3 text-[14px] font-semibold">{event.title}</div>
      <p className="mt-2 text-[13px] text-muted leading-snug">{event.desc}</p>
    </div>
  );
}

function RelatedCard({ stock }: { stock: Stock }) {
  return (
    <Link
      to={`/stock/${stock.ticker}`}
      className="rounded-card border hairline p-4 hover:bg-surface transition-colors flex flex-col justify-between min-h-[170px]"
      data-testid={`related-${stock.ticker}`}
    >
      <Logo ticker={stock.ticker} size={36} />
      <div>
        <div className="text-[14px] font-semibold leading-snug">{stock.name}</div>
        <div
          className={`mt-1 text-[13px] font-semibold num ${
            stock.changePct >= 0 ? 'text-mint-deep' : 'text-loss'
          }`}
        >
          {stock.changePct >= 0 ? '▲' : '▼'} {formatPct(stock.changePct, { withSign: false })}
        </div>
        <div className="mt-3 flex flex-wrap gap-1.5">
          <TagPill>{stock.subIndustry}</TagPill>
          <TagPill>UEMOA</TagPill>
        </div>
      </div>
    </Link>
  );
}

function TagPill({ children }: { children: React.ReactNode }) {
  return (
    <span className="px-2 py-0.5 rounded-pill bg-surface text-[10.5px] text-muted font-medium">
      {children}
    </span>
  );
}
